"""Checks for the Final Assessment coding challenge, Python (basic, 10 minutes). Do not edit this file.

Run every check from the assessment folder:  python -m pytest -q
Your extract.py is imported inside each check, so each check reports its own result.
"""

import importlib
import sys
from decimal import Decimal
from pathlib import Path

LAB = Path(__file__).resolve().parent.parent
STARTER = LAB / "starter"
FIXTURE = LAB / "fixtures" / "transactions.jsonl"
if str(STARTER) not in sys.path:
    sys.path.insert(0, str(STARTER))


def run_validate(records):
    """Import your extract.py now and call validate on the given records."""
    extract = importlib.import_module("settlement.extract")
    result = extract.validate(records)
    try:
        accepted, rejected = result
    except (TypeError, ValueError):
        raise AssertionError("validate must return (accepted, rejected)") from None
    return list(accepted), list(rejected)


def fields_as_a_set(rejected):
    """Rejected entries with each 'fields' list put in sorted order, so a check compares
    which names are there. Only check4 checks the order of the names."""
    entries = []
    for entry in rejected:
        if isinstance(entry, dict) and isinstance(entry.get("fields"), list):
            entry = {**entry, "fields": sorted(entry["fields"], key=str)}
        entries.append(entry)
    return entries


def transaction_class():
    return importlib.import_module("settlement.models").Transaction


def test_check1_valid_records_become_transactions():
    accepted, rejected = run_validate([
        {"txn_id": "T1", "account": "ACCT-1", "amount": "10.50", "currency": " usd "},
        {"txn_id": "T2", "account": "ACCT-2", "amount": "7", "currency": "EUR", "merchant": "Contoso Coffee"},
    ])
    Transaction = transaction_class()
    assert [type(t) for t in accepted] == [Transaction, Transaction], (
        "accepted must hold one Transaction (built from the record) for each valid record"
    )
    assert [(t.txn_id, t.currency, t.amount) for t in accepted] == [
        ("T1", "USD", Decimal("10.50")),
        ("T2", "EUR", Decimal("7")),
    ], "accepted must hold the validated Transactions, in input order"
    assert rejected == [], "valid records must not appear in rejected"


def test_check2_rejected_entry_names_the_failed_fields():
    accepted, rejected = run_validate([
        {"txn_id": "T7", "account": "ACCT-7", "amount": "0", "currency": "US"},
    ])
    assert accepted == [], "a record that fails validation must not be accepted"
    assert fields_as_a_set(rejected) == [{"txn_id": "T7", "fields": ["amount", "currency"]}], (
        "a rejected entry is {'txn_id': the record's txn_id, 'fields': the field names from each error's loc}"
    )


def test_check3_a_record_without_txn_id_is_reported_with_none():
    accepted, rejected = run_validate([
        {"account": "ACCT-3", "amount": "5", "currency": "USD"},
    ])
    assert accepted == [], "a record without txn_id fails validation"
    assert rejected == [{"txn_id": None, "fields": ["txn_id"]}], (
        "a record without txn_id is reported with 'txn_id': None (use raw.get('txn_id'))"
    )


def test_check4_field_names_are_sorted():
    # Six fields fail. The errors come in the model's field order; a set has no fixed order.
    accepted, rejected = run_validate([
        {"txn_id": "T4", "account": 7, "amount": "0", "currency": "US", "cardholder": 42, "merchant": 99, "status": 5},
    ])
    expected = ["account", "amount", "cardholder", "currency", "merchant", "status"]
    assert rejected == [{"txn_id": "T4", "fields": expected}], (
        "'fields' must be a list of the field names sorted A to Z (use sorted), not in the order of the errors "
        f"or of a set: expected {expected}"
    )


def test_check5_keeps_going_and_keeps_input_order():
    accepted, rejected = run_validate([
        {"txn_id": "A", "account": "ACCT-1", "amount": "-1", "currency": "USD"},
        {"txn_id": "B", "account": "ACCT-1", "amount": "1", "currency": "USD"},
        {"txn_id": "C", "account": "ACCT-1", "amount": "2", "currency": "USDX"},
        {"txn_id": "D", "account": "ACCT-1", "amount": "3", "currency": "usd"},
    ])
    assert [t.txn_id for t in accepted] == ["B", "D"], (
        "a bad record must not stop validation: every later valid record is still accepted, in input order"
    )
    assert [r["txn_id"] for r in rejected] == ["A", "C"], "rejected entries must stay in input order"


def test_check6_records_can_be_a_one_pass_generator():
    raw = [
        {"txn_id": "G1", "account": "ACCT-1", "amount": "4", "currency": "USD"},
        {"txn_id": "G2", "account": "ACCT-1", "amount": "0", "currency": "US"},
        {"txn_id": "G3", "account": "ACCT-2", "amount": "6", "currency": "gbp"},
    ]
    accepted, rejected = run_validate(record for record in raw)
    assert [t.txn_id for t in accepted] == ["G1", "G3"], (
        "validate must work on a generator, which can be looped over only once: loop over the records one time"
    )
    assert fields_as_a_set(rejected) == [{"txn_id": "G2", "fields": ["amount", "currency"]}], (
        "from a generator, rejected must be [{'txn_id': 'G2', 'fields': ['amount', 'currency']}]"
    )


def test_check7_the_fixture_batch_end_to_end():
    extract = importlib.import_module("settlement.extract")
    accepted, rejected = run_validate(extract.read_jsonl(FIXTURE))
    assert [t.txn_id for t in accepted] == [
        "T1001", "T1002", "T1004", "T1002", "T1006", "T1007", "T1001", "T1007",
    ], "fixtures/transactions.jsonl has 8 valid records"
    assert rejected == [
        {"txn_id": "T1003", "fields": ["amount"]},
        {"txn_id": None, "fields": ["txn_id"]},
        {"txn_id": "T1005", "fields": ["currency"]},
        {"txn_id": "T1008", "fields": ["amount"]},
    ], "fixtures/transactions.jsonl has 4 rejected records"
